import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"30、【離】 離下離上","description":"周易集註 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"周易集註 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/jizhu/034.md","filePath":"classics/jizhu/034.md"}'),l={name:"classics/jizhu/034.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><p>離者麗也，明也。一陰附麗於上下之陽，麗之義也;中虛，明之義也。離為火，火無常形，附物而明，邵子所謂火用以薪傳是也。《序卦》：“坎者陷也，陷必有所麗，故受之以離。”火中虛而暗，以其陰也;水中實而明，以其陽也。有明必有暗，有晝必有夜，理之常也，所以次坎。</p><p>六二居下離之中則正，六五居上離之中則不正，故利於正而後亨。牛順物，牝牛則順之至也。畜牝牛者，養順德也。養順德於中者，正所以消其炎上之燥性也，故吉。</p><p>《彖》曰：離，麗也。日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正，故亨，是以畜牝牛吉也。</p><p>釋卦名義並卦辭。五為天位，故上離有日月麗天之象，此以氣麗氣者也。二為地位，故下離有百穀草木麗土之象，此以形麗形者也。離附物，故有氣有形。重明者，上離明，下離明也。上下君臣皆麗乎正，則可以化成天下，而成文明之俗矣。柔麗乎中正者，分言之，六五麗乎中，六二麗乎中正也;總言之，柔皆麗乎中正也。惟其中正，所以利貞而後亨。惟柔中正而後亨，所以當畜牝牛，養其柔順中正之德，而後吉也。</p><h3 id="《象》曰-明兩作-離-大人以繼明照於四方。" tabindex="-1">《象》曰：明兩作，離，大人以繼明照於四方。 <a class="header-anchor" href="#《象》曰-明兩作-離-大人以繼明照於四方。" aria-label="Permalink to “《象》曰：明兩作，離，大人以繼明照於四方。”">​</a></h3><p>作者起也，兩作者，一明而兩作也。言今日明，明日又明也，繼明如雲聖繼聖也。以人事論，乃日新又新，緝熙不已也。照於四方者，光被四表也。大人以德言則聖人，以位言則王者。其所謂明者，內而一心，外而應事接物，皆明也。是以達事理，辨民情，天下之邪正得失皆得而見之，不必以察為明，而明照於四方矣。重明者，上下明也。繼明者，前後明也。《彖》言二五君臣，故以重明言之。《象》言明兩作，皆君也，故以繼明言之。</p><p>初九，履錯然，敬之，無咎。</p><p>履者行也，進也。錯者雜也，交錯也。《詩傳》雲“東西為交，邪行為錯”，本爻陽剛，陽性上進;本卦離火，火性炎上，皆有行之之象，故曰履。又變艮，綜震足，亦履之象也。艮為徑路，交錯之象也。然者，語助辭。錯然者，剛則躁，明則察，二者交錯於胸中，未免東馳西走，惟敬以直內，則安靜而不躁妄，主一而不過察，則敬者醫錯之藥也，故無咎。無咎者，剛非躁，明非察也。</p><p>初九以剛居下，而處明體，剛明交錯，故有履錯然之象，惟敬則無此咎矣，故教佔者以此。</p><h3 id="《象》曰-履錯之敬-以闢咎也。闢音避" tabindex="-1">《象》曰：履錯之敬，以闢咎也。闢音避 <a class="header-anchor" href="#《象》曰-履錯之敬-以闢咎也。闢音避" aria-label="Permalink to “《象》曰：履錯之敬，以闢咎也。闢音避”">​</a></h3><p>避者回也，敬則履錯之咎，皆迴避矣。</p><p>六二，黃離，元吉。</p><p>黃中色，坤為黃，離中爻乃坤土，黃之象也。離者附麗也，黃離者，言麗乎中也，即柔麗乎中正也。以人事論，乃順以存心，而不邪側;順以處事，而不偏倚是也。吉者，無所處而不當也。八卦正位，離在二，故元吉。</p><p>六二柔麗乎中，而得其正，故有黃離之象。佔者得此，大吉之道也，故元吉。</p><h3 id="《象》曰-黃離元吉-得中道也。" tabindex="-1">《象》曰：黃離元吉，得中道也。 <a class="header-anchor" href="#《象》曰-黃離元吉-得中道也。" aria-label="Permalink to “《象》曰：黃離元吉，得中道也。”">​</a></h3><p>得中道以成中德，所以凡事無過不及而元吉。</p><p>九三，日昃之離，不鼓缶而歌，則大耋之嗟，兇。</p><p>變震為鼓，鼓之象也。離為大腹，又中虛，缶之象也。中爻兌口，歌與嗟之象也。缶乃常用之物，鼓缶者，樂其常也。凡人歌樂必用鐘鼓琴瑟，則非樂其常矣。若王羲之所謂“年在桑榆”“賴絲竹陶寫”即非樂其常矣。蓋絲竹乃富貴所用之物，貧賤無絲竹者，將何陶寫哉?故鼓缶而歌者，即席前所見之物，以鼓之，乃安其常也。人壽八十曰耋，喜則歌，憂則嗟，嗟者歌之反。</p><p>重離之間，前明將盡，後明當繼之時也，故有日昃之象。然盛衰倚伏，天運之常，人生至此，樂天知命，鼓缶而歌，以安其日用之常分可也。此則達者之事，若不能安常以自樂，徒慼慼於大耋之嗟，則非為無益，適自速其死矣，何兇如之。故又戒佔者，不當如此。</p><h3 id="《象》曰-日昃之離-何可久也。" tabindex="-1">《象》曰：日昃之離，何可久也。 <a class="header-anchor" href="#《象》曰-日昃之離-何可久也。" aria-label="Permalink to “《象》曰：日昃之離，何可久也。”">​</a></h3><p>日既傾昃，明豈能久。</p><p>九四，突如其來如，焚如，死如，棄如。</p><p>突者灶突也。離中虛，灶突之象也。突如其來如者，下體之火，如灶突而炎上也。火性炎上，三之舊火既上於四，而不能回於其三，四之新火又發，五得中居尊，四之火又不敢犯乎其五，上下兩無所容，則火止於四而已，故必至於焚如死如，成灰棄如，而後已也。如者，語助辭。此爻暴秦似之。秦法如火，始皇舊火也，二世新火也，故至死棄而後已。坎性下，三在下卦之上，故曰來，此來而下者也。火性上，四在上卦之下，故曰來，此來而上者也。來而下，必至坎窞而後已;來而上，必至死棄而後已。</p><p>四不中正，當兩火交相接之時，不能容於其中，故有此象，佔者之兇可知矣。</p><h3 id="《象》曰-突如其來如-無所容也。" tabindex="-1">《象》曰：突如其來如，無所容也。 <a class="header-anchor" href="#《象》曰-突如其來如-無所容也。" aria-label="Permalink to “《象》曰：突如其來如，無所容也。”">​</a></h3><p>三爻上而不能反，三不能容也。五中尊*而不敢犯，五不能容也。</p><ul><li>“中尊”應作“居尊”。</li></ul><p>六五，岀涕沱若，戚嗟若，吉。</p><p>涕，沱貌。離錯坎，涕若之象也;又加憂，戚之象也。中爻兌口，嗟之象也。出涕沱若者，憂懼之徵於色也。戚嗟若者，憂懼之發於聲也。二五皆以柔麗乎剛，二之辭安，五之辭危者，二中正，五不正故也。</p><p>六五以柔居尊而守中，有文明之德，然附麗於強剛之間，若不自恃其文明與其中德，能憂懼如此，然後能吉。戒佔者當如此。</p><h3 id="《象》曰-六五之吉-離王公也。離音麗" tabindex="-1">《象》曰：六五之吉，離王公也。離音麗 <a class="header-anchor" href="#《象》曰-六五之吉-離王公也。離音麗" aria-label="Permalink to “《象》曰：六五之吉，離王公也。離音麗”">​</a></h3><p>王指五，公指上九。離王公者，言附麗於王之公也。王與公相麗，陰陽相資，故吉。不言四者，四無所容，而上九能正邦也。</p><p>上九：王用岀徵有嘉，折首，獲匪其醜，無咎。</p><p>王指五，離為日，王之象也。用者用上九也，五附麗於上九，用之之象也。有嘉者，嘉上九也，即王三錫命也。折首獲匪其醜，即可嘉之事也。離為戈兵，變為震動，戈兵震動，出征之象也。王用上九專征，可謂寵之至矣。為上九者，若不分其首，從而俱戮之，是火炎昆岡，安得可嘉?又安得無咎哉?折首者，折取其魁首，即殲厥渠魁也。獲匪其醜者，執獲不及其小丑，即脅從罔治也。幹為首，首象陽，醜象陰。明夷外卦錯幹，故為大首。本爻乾陽，且離為上稿，折其首之象也。本卦陽多陰少，陰乃二五君臣，無群小之醜，獲匪其醜之象也。無咎者，勇足以折首，而仁及於小丑也。王用出徵有嘉一句，折首一句，獲匪其醜一句。</p><p>上九，以陽剛之才，故有王用出徵有嘉之象。又當至明之極，首從畢照，故又有出征惟折其首，不及於醜之象，乃無咎之道也，故其象佔如此。</p><h3 id="《象》曰-王用岀徵-以正邦也。" tabindex="-1">《象》曰：王用岀徵，以正邦也。 <a class="header-anchor" href="#《象》曰-王用岀徵-以正邦也。" aria-label="Permalink to “《象》曰：王用岀徵，以正邦也。”">​</a></h3><p>徵之為言正也，寇賊亂邦，故正之。</p>',38)])])}const m=e(l,[["render",t]]);export{_ as __pageData,m as default};
